+		}

 		if (!non_swap_entry(entry))
 			goto fault;
@@ -488,7 +490,6 @@ static int hmm_vma_walk_hugetlb_entry(pte_t *pte, unsigned long hmask,

 	i = (start - range->start) >> PAGE_SHIFT;
