 469                 pch_i2c_init(adap);
 470                 return -EAGAIN;
 471         } else { /* wait-event timeout */
 472                 pch_i2c_stop(adap);
		     // Your current fixes added here
 473                 return -ETIME;
 474         }
 	     return 0;

It is only pseudo-code, but I think it can be done and will help the driver.

